mapper.update:
	UPDATE  /* isry.couns.constt.bbscrs.mapper.BbscrsListMapper.updateBbscrsIndv : 연계상담게시판 수정 */
            AYA120  
	SET
            SXDC_SE_CD                                  =       #{SXDC_SE_CD}                                   /*  성별구분코드                                    */
        ,   NOW_AGE                                     =       #{NOW_AGE}                                      /*  현재연령                                          */
        ,   RGN_NM                                      =       #{RGN_NM}                                       /*  지역명                                             */
        ,   TRPR_TELNO                                  =       #{TRPR_TELNO}                                   /*  대상자전화번호암호화                        */
        ,   MBL_TELNO_ENCPT                             =       C##RG.ENC_B64(#{MBL_TELNO_ENCPT})            /*  휴대전화번호암호화                           */
        ,   TRPR_EML_ADDR_ENCPT                         =       C##RG.ENC_B64(#{TRPR_EML_ADDR_ENCPT})        /*  대상자이메일주소암호화                     */
        ,   CRISIS_TYPE_SE_CD                           =       #{CRISIS_TYPE_SE_CD}                            /*  위기유형구분코드                              */
        ,   CLIENA_NM_ENCPT                             =       C##RG.ENC_B64(#{CLIENA_NM_ENCPT})            /*  내담자명암호화                                 */
        ,   APEAL_SUMRY_CN                              =       #{APEAL_SUMRY_CN}                               /*  호소요약내용                                    */
        ,   DSCSN_YMD                                   =       SUBSTR(#{DSCSN_YMD}, 0, 8)                      /*  상담일자                                          */
        ,   DSCSN_HR                                    =       #{DSCSN_HR}                                     /*  상담시간                                          */
        ,   DGDGR_SE_CD                                 =       #{DGDGR_SE_CD}                                  /*  위험도구분코드                                 */
        ,   CHRO_NO                                     =       #{CHRO_NO}                                      /*  채팅방번호                                       */
        ,   MBLA_CASE_SITE_ADDR                         =       #{MBLA_CASE_SITE_ADDR}                          /*  모바일사례사이트주소                        */
        ,   MBLA_PVSN_PURPS_SE_CD                       =       #{MBLA_PVSN_PURPS_SE_CD}                        /*  모바일제공목적구분코드                     */
        ,   PVSN_SHAPE_TLPHON_YN                        =       #{PVSN_SHAPE_TLPHON_YN}                         /*  제공형태전화여부                              */
        ,   PVSN_SHAPE_EML_YN                           =       #{PVSN_SHAPE_EML_YN}                            /*  제공형태이메일여부                           */
        ,   PVSN_SHAPE_SYS_YN                           =       #{PVSN_SHAPE_SYS_YN}                            /*  제공형태시스템여부                           */
        ,   UTZTN_PURPS_RSTRCT_MATTER_OBSRY_YN          =       #{UTZTN_PURPS_RSTRCT_MATTER_OBSRY_YN}           /*  이용목적제약사항준수여부                  */
        ,   EMRG_RESC_YN                                =       #{EMRG_RESC_YN}                                 /*  긴급구조여부                                    */
        ,   SPCLTY_INST_DRCT_LINK_YN                    =       #{SPCLTY_INST_DRCT_LINK_YN}                     /*  전문기관직접연계여부                        */
        ,   UTZTN_PSBLTY_INST_INFO_PVSN_YN              =       #{UTZTN_PSBLTY_INST_INFO_PVSN_YN}               /*  이용가능기관정보제공여부                  */
        ,   DCLR_MTHD_GUIDAN_YN                         =       #{DCLR_MTHD_GUIDAN_YN}                          /*  신고방법안내여부                              */
        ,   ETC_RELATA_INFO_PVSN_YN                     =       #{ETC_RELATA_INFO_PVSN_YN}                      /*  기타관련정보제공여부                        */
        ,   EMTNL_BACKIN_YN                             =       #{EMTNL_BACKIN_YN}                              /*  정서적지지여부                                 */
        ,   CHRCTR_YN                                   =       #{CHRCTR_YN}                                    /*  문자여부                                          */
        ,   TLPHON_YN                                   =       #{TLPHON_YN}                                    /*  전화여부                                          */
        ,   NOTE_YN                                     =       #{NOTE_YN}                                      /*  쪽지여부                                          */
        ,   EML_GUIDAN_YN                               =       #{EML_GUIDAN_YN}                                /*  이메일안내여부                                 */
        ,   YNGBGS_DSCSN_WLFAR_CNTER_RQST_YN            =       #{YNGBGS_DSCSN_WLFAR_CNTER_RQST_YN}             /*  청소년상담복지센터의뢰여부               */
        ,   FAM_RQST_YN                                 =       #{FAM_RQST_YN}                                  /*  가족의뢰여부                                    */
        ,   DT_CACE_SHELTR_RQST_YN                      =       #{DT_CACE_SHELTR_RQST_YN}                       /*  일시보호소쉼터의뢰여부                     */
        ,   EMRG_RESC_RQST_YN                           =       #{EMRG_RESC_RQST_YN}                            /*  긴급구조의뢰여부                              */
        ,   LEADER_RQST_YN                              =       #{LEADER_RQST_YN}                               /*  지도자의뢰여부                                 */
        ,   YNGBGS_DSCSN_WLFAR_CNTER_RQST_MTHD_SE_CD    =       #{YNGBGS_DSCSN_WLFAR_CNTER_RQST_MTHD_SE_CD}     /*  청소년상담복지센터의뢰방법구분코드   */
        ,   FAM_RQST_MTHD_SE_CD                         =       #{FAM_RQST_MTHD_SE_CD}                          /*  가족의뢰방법구분코드                        */
        ,   DT_CACE_SHELTR_RQST_MTHD_SE_CD              =       #{DT_CACE_SHELTR_RQST_MTHD_SE_CD}               /*  일시보호소쉼터의뢰방법구분코드         */
        ,   EMRG_RESC_RQST_MTHD_SE_CD                   =       #{EMRG_RESC_RQST_MTHD_SE_CD}                    /*  긴급구조의뢰방법구분코드                  */
        ,   LEADER_RQST_MTHD_SE_CD                      =       #{LEADER_RQST_MTHD_SE_CD}                       /*  지도자의뢰방법구분코드                     */
        ,   ETC_SPCLTY_INST_RQST_MTHD_SE_CD             =       #{ETC_SPCLTY_INST_RQST_MTHD_SE_CD}              /*  기타전문기관의뢰방법구분코드            */
        ,   PIC_NM_ENCPT                                =       C##RG.ENC_B64(#{PIC_NM_ENCPT})               /*  담당자명암호화                                 */
        ,   RLTPSN_CTTPC_TELNO                          =       #{RLTPSN_CTTPC_TELNO_ENCPT}                     /*  관련자연락처전화번호암호화               */   
        ,   FLNM_PVSN_YN                                =       #{FLNM_PVSN_YN}                                 /*  성명제공여부                                    */  
        ,   AGEA_PVSN_YN                                =       #{AGEA_PVSN_YN}                                 /*  나이제공여부                                    */  
        ,   SXDC_PVSN_YN                                =       #{SXDC_PVSN_YN}                                 /*  성별제공여부                                    */  
        ,   TELNO_PVSN_YN                               =       #{TELNO_PVSN_YN}                                /*  전화번호제공여부                              */    
        ,   ADDR_PVSN_YN                                =       #{ADDR_PVSN_YN}                                 /*  주소제공여부                                    */  
        ,   SCHL_INFO_PVSN_YN                           =       #{SCHL_INFO_PVSN_YN}                            /*  학교정보제공여부                              */    
        ,   APEAL_PROBM_PVSN_YN                         =       #{APEAL_PROBM_PVSN_YN}                          /*  호소문제제공여부                              */    
        ,   MBLA_RQST_PVSN_ETC_YN                       =       #{MBLA_RQST_PVSN_ETC_YN}                        /*  모바일의뢰제공기타여부                     */ 
        ,   ETC_CN                                      =       #{ETC_CN}                                       /*  기타내용                                          */  
        ,   CLIENA_ID                                   =       #{CLIENA_ID}                                    /*  내담자아이디                                    */
        ,   CONSTT_ID                                   =       #{CONSTT_ID}                                    /*  상담원아이디                                    */
        ,   RQST_INST_INFO_PVSN_NDLS_YN                 =       #{RQST_INST_INFO_PVSN_NDLS_YN}                  /*  의뢰기관정보제공불필요여부               */ 
        ,   ETC_SPCLTY_INST_RQST_YN                     =       #{ETC_SPCLTY_INST_RQST_YN}                      /*  기타전문기관의뢰여부                        */ 
        ,   RLVT_NAPC_YN                                =       #{RLVT_NAPC_YN}                                 /*  해당사항없음여부                              */ 
        ,   LAST_MDFR_ID                                =       #{LAST_MDFR_ID}
        ,   LAST_MDFCN_DT                               =       SYSDATE
        , YC1388_YN                                           = #{YC1388_YN}
        , MHW129_YN                                           = #{MHW129_YN}
        , SUNFLO_CNTER_YN                                     = #{SUNFLO_CNTER_YN}
        , PRSTT_DMGE_CSLC_YN                                  = #{PRSTT_DMGE_CSLC_YN}
        , SUCDE_PREVNT_CNTER_YN                               = #{SUCDE_PREVNT_CNTER_YN}
        , SCHL_VIOLNC_SOS_SUGR_YN                             = #{SCHL_VIOLNC_SOS_SUGR_YN}
        , CHIL_PRTCTN_SPCLTY_INST_YN                          = #{CHIL_PRTCTN_SPCLTY_INST_YN}
        , HEALTH_HOUSEK_SPRT_CNTER_YN                         = #{HEALTH_HOUSEK_SPRT_CNTER_YN}
        , OFCDC_YN                                            = #{OFCDC_YN}
        , ALTRV_SCHL_YN                                       = #{ALTRV_SCHL_YN}
        , YNGBGS_LABOR_PRTCTN_CNTER_YN                        = #{YNGBGS_LABOR_PRTCTN_CNTER_YN}
        , ADDC_MNG_UNITY_SPRT_CNTER_YN                        = #{ADDC_MNG_UNITY_SPRT_CNTER_YN}
        , YNGBGS_SECU_CNTER_YN                                = #{YNGBGS_SECU_CNTER_YN}
        , SAFETY_DREAMA_CHIL_FEMALE_DSPSN_POLC_SPRT_CNTER_YN  = #{SAFETY_DREAMA_CHIL_FEMALE_DSPSN_POLC_SPRT_CNTER_YN}
        , WH1366_YN                                           = #{WH1366_YN}
        , SXVLC_CSLC_YN                                       = #{SXVLC_CSLC_YN}
        , UNMRMT_FANSO_FTHOLD_INST_YN                         = #{UNMRMT_FANSO_FTHOLD_INST_YN}
        , MIND_HEALTH_WLFAR_CNTER_YN                          = #{MIND_HEALTH_WLFAR_CNTER_YN}
        , POLICE_CYBER_SEAD_YN                                = #{POLICE_CYBER_SEAD_YN}
        , HMVLN_CSLC_YN                                       = #{HMVLN_CSLC_YN}
        , KOLEAI_YN                                           = #{KOLEAI_YN}
        , YNGBGS_SPRT_CNTER_DREAM_YN                          = #{YNGBGS_SPRT_CNTER_DREAM_YN}
        , EMPLYA_CNTER_YN                                     = #{EMPLYA_CNTER_YN}
        , YNGBGS_LABOR_INTRRT_CNTER_YN                        = #{YNGBGS_LABOR_INTRRT_CNTER_YN}

        , SMRE_CNTER_YN                                       = #{SMRE_CNTER_YN}
        , LILI_YN                                             = #{LILI_YN}
        , ETC_SPCLTY_INST_ETC_YN                              = #{ETC_SPCLTY_INST_ETC_YN}
        , ETC_SPCLTY_INST_NM                                  = #{ETC_SPCLTY_INST_NM}
    WHERE   1=1
        AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
        AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}

UPDATE  /* isry.couns.constt.bbscrs.mapper.BbscrsListMapper.updateBbscrsIndv100 : 연계상담게시판 수정 */
        AYE100  
SET
        CRISIS_TYPE_SE_CD                           =       #{CRISIS_TYPE_SE_CD}                            /*  위기유형구분코드                              */
    ,   LAST_MDFR_ID                                =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT                               =       SYSDATE        
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}

UPDATE /* isry.couns.constt.bbscrs.mapper.BbscrsListMapper.updateCrisisBoard : 채팅내역 위기유형등록 */
       AYA110  
   SET CRISIS_TYPE_SE_CD = #{CRISIS_TYPE_SE_CD} 
     , LAST_MDFR_ID      = #{LAST_MDFR_ID}
     , LAST_MDFCN_DT     = SYSDATE
 WHERE BBSCTT_ESNTAL_NO=       #{BBSCTT_ESNTAL_NO}
